using System;
using System.IO;
using System.Linq;
using NetworkHub.App;
using NetworkHub.Dns;
namespace NetworkHub.Desktop;
internal static class TestsDnsSessions
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Reject(Action action){try{action();}catch(Exception ex)when(ex is DnsException or IOException or InvalidDataException){return;}throw new Exception("Unsafe plan was accepted");}
    static DnsFamilySettings Encrypted(DnsProfile profile,ulong flags=2)=>new(DnsMode.Manual,profile.IPv4,profile.IPv4){Encryption=profile.IPv4.Select(ip=>new DnsDohSettings(ip,profile.Doh,flags)).ToArray()};
    internal static void Run(Action<string,Action> test,Shell shell,AppFiles files)
    {
        test("DNS sessions: altered checkpoint readback prevents any automatic write",()=>{var fake=TestsDns.Fixture();var store=new TestsDns.FakeStore{ReadOverride=j=>j with{RollbackTarget=j.Before with{DependencyFingerprint="corrupt-checkpoint"}}};Reject(()=>new DnsTransaction(fake,fake,store,"test").Automatic(fake.State));Check(fake.Writes==0,"Unverified checkpoint permitted a write");});
        test("DNS sessions: automatic write then error compensates exact encrypted original",()=>{var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=Encrypted(DnsProfiles.All[1])};var original=fake.State;bool once=false;fake.AfterWrite=()=>{if(!once){once=true;throw new IOException("Injected error after mutation");}};var store=new TestsDns.FakeStore();Reject(()=>new DnsTransaction(fake,fake,store,"test").Automatic(original));Check(fake.Writes==2&&fake.State.SameConfiguration(original)&&store.Journal!.Phase==DnsPhase.Restored,"Post-write failure lost encryption or rollback");});
        test("DNS sessions: externally configured encrypted Xbox to automatic and exact original",()=>{var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=Encrypted(DnsProfiles.All[1])};var before=fake.State;var store=new TestsDns.FakeStore();var tx=new DnsTransaction(fake,fake,store,"test");tx.Automatic(before);Check(fake.State.IPv4.Mode==DnsMode.Automatic&&fake.State.IPv4.Servers.Length==0&&fake.State.IPv4.Encryption.Length==0&&fake.State.IPv6.SameConfiguration(before.IPv6),"Reset changed wrong state");Check(store.Journal!.Before.SameConfiguration(before),"Pre-reset manual baseline missing");tx.Restore(before.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(before),"Xbox DoH original lost");});
        test("DNS sessions: external Comss automatic restores original Comss",()=>{var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=Encrypted(DnsProfiles.All[0],6)};var before=fake.State;var tx=new DnsTransaction(fake,fake,new TestsDns.FakeStore(),"test");tx.Automatic(before);tx.Restore(before.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(before),"Comss fallback policy lost");});
        test("DNS sessions: automatic no-op and repeated reset preserve backup",()=>{var fake=TestsDns.Fixture();var original=fake.State;var store=new TestsDns.FakeStore();var tx=new DnsTransaction(fake,fake,store,"test");tx.Automatic(original);var id=store.Journal!.Id;tx.Automatic(fake.State);Check(fake.Writes==1&&store.Journal.Id==id&&store.Journal.Before.SameConfiguration(original),"Repeated reset rewrote original");tx.Restore(original.AdapterId,fake.State.Fingerprint());fake.State=fake.State with{IPv4=new(DnsMode.Automatic,Array.Empty<string>(),new[]{"192.0.2.1"})};int count=fake.Writes;tx.Automatic(fake.State);Check(fake.Writes==count,"Already automatic wrote Windows");});
        test("DNS sessions: profile switches and automatic preserve first baseline after restart",()=>{string path=Path.Combine(files.Data,"Dns-session-restart",Guid.NewGuid().ToString("N"));var fake=TestsDns.Fixture(path);var original=fake.State;var store=new DnsFileJournalStore(path,"test");var tx=new DnsTransaction(fake,fake,store,"test");foreach(var profile in new[]{DnsProfiles.All[0],DnsProfiles.All[1],DnsProfiles.All[0]}){var target=fake.State with{IPv4=DnsProfiles.ProfilePlan(fake.State.IPv4,profile.IPv4,profile,true,false)};tx.Apply(fake.State,target,new[]{DnsFamily.IPv4},profile.Id,true,profile.Name);}tx.Automatic(fake.State);Check(store.Load(original.AdapterId)!.History.Length==4&&store.Load(original.AdapterId)!.Before.SameConfiguration(original),"Session replaced original");var restart=TestsDns.Fixture(path);new DnsTransaction(restart,restart,new DnsFileJournalStore(path,"test"),"test").Restore(original.AdapterId,restart.State.Fingerprint());Check(restart.State.SameConfiguration(original),"Offline restart failed");});
        test("DNS sessions: failed new profile compensates to previous managed state",()=>{var fake=TestsDns.Fixture();var original=fake.State;var store=new TestsDns.FakeStore();var tx=new DnsTransaction(fake,fake,store,"test");var comss=fake.State with{IPv4=Encrypted(DnsProfiles.All[0])};tx.Apply(fake.State,comss,new[]{DnsFamily.IPv4},"comss",true,"ComssDNS");var previous=fake.State;bool fail=true;fake.BeforeWrite=_=>{if(fail){fail=false;throw new IOException("Injected write failure");}};Reject(()=>tx.Apply(previous,previous with{IPv4=Encrypted(DnsProfiles.All[1])},new[]{DnsFamily.IPv4},"xbox",true,"Xbox DNS"));Check(fake.State.SameConfiguration(previous)&&store.Journal!.Before.SameConfiguration(original)&&store.Journal.Phase==DnsPhase.Applied,"Failed switch lost session");fake.BeforeWrite=null;tx.Restore(original.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(original),"Initial state no longer recoverable");});
        test("DNS sessions: failed automatic preserves manual original",()=>{var fake=TestsDns.Fixture();var before=fake.State;var store=new TestsDns.FakeStore();var tx=new DnsTransaction(fake,fake,store,"test");fake.BeforeWrite=_=>throw new IOException("Denied reset");Reject(()=>tx.Automatic(before));Check(fake.State.SameConfiguration(before)&&store.Journal!.Before.SameConfiguration(before),"Reset error lost original");});
        test("DNS profiles: automatic source applies reviewed presets with DoH",()=>{foreach(var profile in DnsProfiles.All.Take(2)){var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=new(DnsMode.Automatic,Array.Empty<string>(),new[]{"192.0.2.1"})};var original=fake.State;var target=original with{IPv4=DnsProfiles.ProfilePlan(original.IPv4,profile.IPv4,profile,true,false)};var tx=new DnsTransaction(fake,fake,new TestsDns.FakeStore(),"test");tx.Apply(original,target,new[]{DnsFamily.IPv4},profile.Id,true,profile.Name);Check(fake.State.IPv4.Encryption.All(p=>p.Flags==2),"Preset DoH not applied");tx.Restore(original.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(original),"Automatic baseline lost");}});
        test("DNS profiles: custom named profiles persist separately from backup",()=>{var store=new DnsProfileStore(Path.Combine(files.Data,"Custom-profiles"));foreach(int count in new[]{1,2}){var profile=new SavedDnsProfile(Guid.NewGuid().ToString("N"),"Fixture custom "+count,new[]{"192.0.2.53","192.0.2.54"}.Take(count).ToArray(),Array.Empty<string>(),"https://dns.example/dns-query",true,true);store.Save(profile);Check(store.Load().Any(p=>p.Id==profile.Id&&p.IPv4.SequenceEqual(profile.IPv4)&&p.Fallback),"Profile reload lost fields");var backend=TestsDns.Fixture();var before=backend.State;var target=before with{IPv4=DnsProfiles.ProfilePlan(before.IPv4,profile.IPv4,new("custom",profile.Name,profile.IPv4,profile.IPv6,profile.Doh,"","",true,""),true,true)};var tx=new DnsTransaction(backend,backend,new TestsDns.FakeStore(),"test");tx.Apply(before,target,new[]{DnsFamily.IPv4},"custom",true,profile.Name);tx.Restore(before.AdapterId,backend.State.Fingerprint());Check(backend.State.SameConfiguration(before),"Custom restore failed");}});
        test("DNS profiles: invalid endpoint and unsupported Windows DoH fail closed",()=>{var before=TestsDns.Fixture().State;foreach(string endpoint in new[]{"http://dns.example/query","https://user:secret@dns.example/query","https://dns.example/query#fragment","https://192.0.2.99/query"})Reject(()=>DnsProfiles.ProfilePlan(before.IPv4,new[]{"192.0.2.53"},new("custom","test",Array.Empty<string>(),Array.Empty<string>(),endpoint,"","",true,""),true,false));var win10=before with{SupportsDoh=false};var target=win10 with{IPv4=Encrypted(DnsProfiles.All[0])};Reject(()=>DnsTransaction.Validate(win10,target,new[]{DnsFamily.IPv4},false,true));DnsTransaction.Validate(win10,win10 with{IPv4=new(DnsMode.Manual,new[]{"192.0.2.99"},Array.Empty<string>())},new[]{DnsFamily.IPv4});});
        test("DNS cache: fixed system command has no network reset arguments",()=>{var plan=DnsCache.Plan();Check(!plan.UseShellExecute&&plan.ArgumentList.SequenceEqual(new[]{"/flushdns"})&&Path.GetFileName(plan.FileName)=="ipconfig.exe","Arbitrary cache command");Check(DnsCache.Clear(true).Contains("simulated",StringComparison.OrdinalIgnoreCase),"Safe cache path not simulated");});
        test("DNS sessions: automatic reset scope is only IPv4",()=>{var before=TestsDns.Fixture().State;Reject(()=>DnsTransaction.Validate(before,before with{IPv6=new(DnsMode.Automatic,Array.Empty<string>(),Array.Empty<string>())},new[]{DnsFamily.IPv6},true,true));var plan=WindowsDnsSettings.AutomaticResetPlan(5,DnsFamily.IPv4);Check(plan.ArgumentList.SequenceEqual(new[]{"interface","ipv4","set","dnsservers","name=5","source=dhcp"}),"IP DHCP or unselected family modified");});
    }
}
